-- Durable, explicit local mock POS dispatch and trusted receipt projection.

CREATE TABLE _dg_native_order_worker_leases(lease_token text PRIMARY KEY,change_id text NOT NULL REFERENCES restaurant_order_dispatches(change_id),mode text NOT NULL CHECK(mode IN('submit','lookup')),request_hash text NOT NULL,runtime_id text NOT NULL,action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),created_at text NOT NULL,expires_at text NOT NULL);
CREATE TABLE _dg_native_order_receipt_origins(event_id text PRIMARY KEY REFERENCES restaurant_pos_callbacks(event_id),action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),runtime_id text NOT NULL,request_hash text NOT NULL,receipt_hash text NOT NULL,ingress text NOT NULL CHECK(ingress IN('worker','callback')),created_at text NOT NULL);
CREATE TABLE _dg_native_order_line_origins(line_id text PRIMARY KEY REFERENCES restaurant_order_lines(id),change_id text NOT NULL REFERENCES restaurant_order_changes(id),event_id text NOT NULL REFERENCES restaurant_pos_callbacks(event_id),quote_id text NOT NULL REFERENCES restaurant_order_quotes(id),line_hash text NOT NULL,runtime_id text NOT NULL);
CREATE TABLE _dg_native_order_kitchen_origins(ticket_id text PRIMARY KEY REFERENCES restaurant_kitchen_tickets(id),line_id text NOT NULL UNIQUE REFERENCES restaurant_order_lines(id),event_id text NOT NULL REFERENCES restaurant_pos_callbacks(event_id),runtime_id text NOT NULL);
CREATE TABLE _dg_native_order_mock_origins(change_id text PRIMARY KEY REFERENCES mock_pos_operations(change_id),action_id text NOT NULL UNIQUE REFERENCES _dg_native_dining_actions(id),runtime_id text NOT NULL,payload_hash text NOT NULL,created_at text NOT NULL);
CREATE TABLE _dg_native_order_receipt_failures(event_id text PRIMARY KEY REFERENCES restaurant_pos_callbacks(event_id),sqlstate text NOT NULL CHECK(length(sqlstate)=5),failure_site text NOT NULL,created_at text NOT NULL);
DO $transport_append$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['_dg_native_order_worker_leases','_dg_native_order_receipt_origins','_dg_native_order_line_origins','_dg_native_order_kitchen_origins','_dg_native_order_mock_origins','_dg_native_order_receipt_failures'] LOOP EXECUTE format('CREATE TRIGGER native_order_transport_immutable BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION dg_native_append_only()',table_value);END LOOP;END;$transport_append$;
CREATE UNIQUE INDEX native_order_one_final_application ON restaurant_pos_callbacks(change_id) WHERE applied=1 AND outcome IN('accepted','rejected');

CREATE FUNCTION dg_native_order_transport_lock(change_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE r restaurants%ROWTYPE;order_value text;
BEGIN
 PERFORM dg_native_reception_runtime(true);SELECT o.order_id INTO order_value FROM _dg_native_order_change_origins o WHERE o.change_id=change_value;SELECT restaurant.* INTO r FROM restaurant_orders current_order JOIN restaurants restaurant ON restaurant.id=current_order.restaurant_id WHERE current_order.id=order_value;
 IF r.id IS NULL THEN PERFORM dg_native_order_error('NOT_FOUND');END IF;PERFORM dg_native_reception_workspace(r.tenant_id,r.workspace_id,true);PERFORM id FROM restaurants WHERE id=r.id FOR UPDATE;PERFORM id FROM restaurant_orders WHERE id=order_value FOR UPDATE;PERFORM id FROM restaurant_order_changes WHERE id=change_value FOR UPDATE;PERFORM change_id FROM restaurant_order_dispatches WHERE change_id=change_value FOR UPDATE;
END;$dg$;

CREATE FUNCTION dg_native_order_transport_action(change_value text,kind_value text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;
BEGIN
 SELECT jsonb_build_object('restaurantId',r.id,'tenantId',r.tenant_id,'workspaceId',r.workspace_id,'partyId',o.party_id,'actorType','worker','actorId',CASE WHEN kind_value='order_receipt' THEN 'system:pos-receipt' ELSE 'system:order-dispatch' END,'actorEpoch',NULL,'grantVersion',NULL,'sessionId',NULL,'accessId',NULL,'focusVersion',NULL,'selectionVersion',NULL) INTO meta FROM restaurant_order_changes c JOIN restaurant_orders o ON o.id=c.order_id JOIN restaurants r ON r.id=o.restaurant_id WHERE c.id=change_value;
 RETURN dg_native_dining_action(meta,kind_value,'party',meta->>'partyId','{}');
END;$dg$;

CREATE FUNCTION dg_native_order_transport_state(change_value text,action_value text,status_value text,message_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;created text;kind_value text;
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id;SELECT created_at,kind INTO created,kind_value FROM _dg_native_dining_actions WHERE id=action_value;
 IF c.status<>status_value THEN PERFORM dg_native_dining_effect(action_value,'restaurant_order_changes',c.id);UPDATE restaurant_order_changes SET status=status_value,version=version+1,updated_at=created WHERE id=c.id;END IF;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET status=CASE WHEN status_value='unknown' THEN 'needs_attention' ELSE status_value END,version=version+1,updated_at=created WHERE id=o.id;
 PERFORM dg_native_order_event(action_value,o.id,c.id,kind_value,message_value);
END;$dg$;

CREATE FUNCTION dg_native_order_worker_claim() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE candidate record;d restaurant_order_dispatches%ROWTYPE;c restaurant_order_changes%ROWTYPE;action_value text;created text;expires text;lease_value text;mode_value text;
BEGIN
 PERFORM dg_native_reception_runtime(true);PERFORM dg_native_order_sweep(NULL);
 FOR candidate IN SELECT dispatch.change_id FROM restaurant_order_dispatches dispatch JOIN _dg_native_order_dispatch_origins origin ON origin.change_id=dispatch.change_id WHERE dispatch.status='queued' AND dispatch.attempts=0 OR dispatch.attempts=1 AND(dispatch.lease_token IS NULL OR dispatch.lease_until<=dg_native_dining_now()) AND(dispatch.status='submitting' OR dispatch.status IN('submitted','unknown') AND(dispatch.query_requested=1 OR dispatch.status='submitted' AND(dispatch.last_lookup_at IS NULL OR dispatch.last_lookup_at<=dg_native_people_iso(clock_timestamp()-interval '1 second')))) ORDER BY dispatch.created_at,dispatch.change_id LIMIT 25 LOOP
  PERFORM dg_native_order_transport_lock(candidate.change_id);SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=candidate.change_id;SELECT * INTO c FROM restaurant_order_changes WHERE id=d.change_id;
  IF d.lease_token IS NOT NULL AND d.lease_until>dg_native_dining_now() OR d.error_code='POS_RECONCILIATION_REQUIRED' OR d.status IN('accepted','rejected','cancelled','stale') THEN CONTINUE;END IF;
  IF d.status='queued' AND d.attempts=0 THEN IF dg_native_order_before_send_reason(d.change_id) IS NOT NULL THEN CONTINUE;END IF;mode_value:='submit';
  ELSIF d.attempts=1 AND(d.status='submitting' OR d.status IN('submitted','unknown') AND(d.query_requested=1 OR d.status='submitted' AND(d.last_lookup_at IS NULL OR d.last_lookup_at<=dg_native_people_iso(clock_timestamp()-interval '1 second')))) THEN mode_value:='lookup';ELSE CONTINUE;END IF;
  action_value:=dg_native_order_transport_action(d.change_id,CASE WHEN mode_value='submit' THEN 'order_send' ELSE 'order_lookup' END);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;lease_value:=gen_random_uuid()::text;expires:=dg_native_people_iso(created::timestamptz+interval '15 seconds');
  PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',d.change_id);
  UPDATE restaurant_order_dispatches SET status=CASE WHEN mode_value='submit' THEN 'submitting' WHEN status='submitting' THEN 'unknown' ELSE status END,attempts=CASE WHEN mode_value='submit' THEN 1 ELSE attempts END,lease_token=lease_value,lease_until=expires,query_requested=0,lookups=lookups+CASE WHEN mode_value='lookup' THEN 1 ELSE 0 END,last_lookup_at=CASE WHEN mode_value='lookup' THEN created ELSE last_lookup_at END,version=version+1,updated_at=created WHERE change_id=d.change_id;
  INSERT INTO _dg_native_order_worker_leases VALUES(lease_value,d.change_id,mode_value,d.request_hash,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),action_value,created,expires);
  IF mode_value='submit' THEN PERFORM dg_native_order_transport_state(d.change_id,action_value,'submitting','已持久登记第一次发送尝试，尚未获得后厨确认。');
  ELSIF d.status='submitting' THEN PERFORM dg_native_order_transport_state(d.change_id,action_value,'unknown','原发送租约已到期，只查询原请求，不另发新单。');END IF;
  RETURN jsonb_build_object('changeId',d.change_id,'leaseToken',lease_value,'expiresAt',expires,'mode',mode_value,'requestHash',d.request_hash);
 END LOOP;RETURN NULL;
END;$dg$;

CREATE FUNCTION dg_native_order_worker_context(change_value text,lease_value text,send_value boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE d restaurant_order_dispatches%ROWTYPE;lease _dg_native_order_worker_leases%ROWTYPE;
BEGIN
 PERFORM dg_native_reception_runtime(true);SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=change_value;SELECT * INTO lease FROM _dg_native_order_worker_leases WHERE lease_token=lease_value AND change_id=d.change_id;
 IF d.change_id IS NULL OR d.lease_token IS DISTINCT FROM lease_value OR lease.lease_token IS NULL OR d.lease_until<=dg_native_dining_now() OR d.lease_until IS DISTINCT FROM lease.expires_at OR lease.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR lease.request_hash<>d.request_hash OR d.request_hash<>dg_native_office_hash(d.request_payload::jsonb) OR d.attempts<>1 OR d.provider_id<>'mock-pos' OR d.simulated<>1 OR d.status NOT IN('submitting','submitted','unknown') OR d.error_code='POS_RECONCILIATION_REQUIRED' THEN PERFORM dg_native_order_error('ORDER_WORKER_LEASE');END IF;
 IF send_value AND lease.mode='submit' AND dg_native_order_transport_source_reason(change_value) IS NOT NULL THEN PERFORM dg_native_order_error('ORDER_SOURCE_EXPIRED');END IF;
 RETURN jsonb_build_object('changeId',d.change_id,'leaseToken',lease_value,'mode',lease.mode,'requestHash',d.request_hash,'request',d.request_payload::jsonb,'scenario',d.config_snapshot::jsonb->>'scenario','expiresAt',lease.expires_at,'sourceExpiresAt',(SELECT q.expires_at FROM restaurant_order_changes c JOIN restaurant_order_quotes q ON q.id=c.confirmed_quote_id WHERE c.id=d.change_id));
END;$dg$;

CREATE FUNCTION dg_native_order_mock_record(change_value text,outcome_value text,action_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE d restaurant_order_dispatches%ROWTYPE;created text;payload jsonb;
BEGIN
 SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=change_value;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;payload:=d.request_payload::jsonb;
 IF d.attempts<>1 OR d.provider_id<>'mock-pos' OR d.simulated<>1 OR outcome_value NOT IN('accepted','rejected') THEN PERFORM dg_native_order_error('POS_RECEIPT_MISMATCH');END IF;
 IF EXISTS(SELECT 1 FROM mock_pos_operations WHERE change_id=d.change_id) THEN RETURN;END IF;
 PERFORM dg_native_dining_effect(action_value,'mock_pos_operations',d.change_id);INSERT INTO mock_pos_operations VALUES(d.change_id,d.restaurant_id,d.request_hash,d.request_payload,'mock-pos:'||d.change_id,coalesce(payload->>'remoteOrderId','mock-order:'||(payload->>'orderId')),outcome_value,2,created);
 INSERT INTO _dg_native_order_mock_origins VALUES(d.change_id,action_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),dg_native_office_hash((SELECT to_jsonb(operation) FROM mock_pos_operations operation WHERE change_id=d.change_id)),created);
END;$dg$;

CREATE FUNCTION dg_native_order_mock_io(change_value text,lease_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE context jsonb;operation mock_pos_operations%ROWTYPE;action_value text;scenario_value text;
BEGIN
 PERFORM dg_native_order_transport_lock(change_value);context:=dg_native_order_worker_context(change_value,lease_value,true);scenario_value:=context->>'scenario';
 IF context->>'mode'='submit' AND scenario_value<>'unresolved' THEN action_value:=dg_native_order_transport_action(change_value,'order_mock_remote');PERFORM dg_native_order_mock_record(change_value,CASE WHEN scenario_value='rejected' THEN 'rejected' ELSE 'accepted' END,action_value);END IF;
 SELECT current_operation.* INTO operation FROM mock_pos_operations current_operation JOIN _dg_native_order_mock_origins origin ON origin.change_id=current_operation.change_id WHERE current_operation.change_id=change_value;
 IF context->>'mode'='submit' AND scenario_value IN('unresolved','response_lost') THEN RETURN jsonb_build_object('errorCode',CASE WHEN scenario_value='unresolved' THEN 'MOCK_RESULT_UNRESOLVED' ELSE 'MOCK_RESPONSE_LOST' END,'receipt',NULL);END IF;
 RETURN jsonb_build_object('errorCode',NULL,'receipt',CASE WHEN operation.change_id IS NOT NULL THEN jsonb_build_object('requestId',operation.change_id,'requestHash',operation.request_hash,'restaurantId',operation.restaurant_id,'remoteRequestId',operation.remote_request_id,'remoteOrderId',operation.remote_order_id,'status',CASE WHEN context->>'mode'='submit' THEN 'submitted' ELSE operation.outcome END,'sequence',CASE WHEN context->>'mode'='submit' THEN 1 ELSE operation.sequence END,'simulated',true,'reasonCode',CASE WHEN context->>'mode'='lookup' AND operation.outcome='rejected' THEN 'MOCK_REJECTED' END) END);
END;$dg$;

CREATE FUNCTION dg_native_order_receipt_conflict(change_value text,event_value text,action_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;d restaurant_order_dispatches%ROWTYPE;created text;message_value text:='可信回执与已有结果或本地业务投影冲突；原请求、库存和回执保留，请由店员向POS核对，不能自动重发。';
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value;SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=c.id;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 PERFORM dg_native_dining_effect(action_value,'restaurant_pos_callbacks',event_value);UPDATE restaurant_pos_callbacks SET conflict=1 WHERE event_id=event_value;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET status=CASE WHEN status IN('accepted','rejected') THEN status ELSE 'unknown' END,error_code='POS_RECONCILIATION_REQUIRED',error_message=message_value,lease_token=NULL,lease_until=NULL,query_requested=0,version=version+1,updated_at=created WHERE change_id=c.id;
 IF c.status NOT IN('accepted','rejected') THEN PERFORM dg_native_dining_effect(action_value,'restaurant_order_changes',c.id);UPDATE restaurant_order_changes SET status='unknown',version=version+1,updated_at=created WHERE id=c.id;END IF;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',c.order_id);UPDATE restaurant_orders SET control_mode='human',attention_reason=message_value,status='needs_attention',version=version+1,updated_at=created WHERE id=c.order_id;PERFORM dg_native_order_event(action_value,c.order_id,c.id,'order_receipt',message_value);
 RETURN jsonb_build_object('duplicate',false,'applied',false,'conflict',true);
END;$dg$;

CREATE FUNCTION dg_native_order_receipt_business(change_value text,event_value text,action_value text,status_value text,receipt jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;q restaurant_order_quotes%ROWTYPE;hold restaurant_inventory_reservations%ROWTYPE;line restaurant_order_lines%ROWTYPE;ticket restaurant_kitchen_tickets%ROWTYPE;snapshot jsonb;item jsonb;created text;ticket_value text;current_total bigint;changed boolean:=false;
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;snapshot:=q.payload::jsonb;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 SELECT coalesce(sum((quantity-cancelled_quantity)*unit_price_minor),0) INTO current_total FROM restaurant_order_lines WHERE order_id=o.id;
 IF q.id IS NULL OR o.pending_change_id IS DISTINCT FROM c.id OR o.content_version<>(snapshot->>'contentVersion')::bigint OR current_total<>(snapshot->>'oldTotalMinor')::bigint THEN PERFORM dg_native_order_error('ORDER_DATA_INCOMPLETE');END IF;
 IF status_value='accepted' THEN
  FOR hold IN SELECT reservation.* FROM restaurant_inventory_reservations reservation JOIN _dg_native_order_reservation_origins origin ON origin.reservation_id=reservation.id WHERE reservation.change_id=c.id AND reservation.status='reserved' ORDER BY reservation.sku_id FOR UPDATE OF reservation LOOP
   PERFORM dg_native_dining_effect(action_value,'restaurant_inventory_reservations',hold.id);UPDATE restaurant_inventory_reservations SET status='committed',updated_at=created WHERE id=hold.id;
  END LOOP;
  FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='reduce' ORDER BY value->>'lineId' LOOP
   SELECT * INTO line FROM restaurant_order_lines WHERE id=item->>'lineId' AND order_id=o.id FOR UPDATE;SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE line_id=line.id FOR UPDATE;
   IF line.id IS NULL OR ticket.id IS NULL OR ticket.pending_cancel_quantity<(item->>'quantity')::bigint OR line.quantity-line.cancelled_quantity-ticket.started_quantity<(item->>'quantity')::bigint THEN PERFORM dg_native_order_error('KITCHEN_QUANTITY_CHANGED');END IF;
   PERFORM dg_native_dining_effect(action_value,'restaurant_order_lines',line.id);UPDATE restaurant_order_lines SET cancelled_quantity=cancelled_quantity+(item->>'quantity')::bigint WHERE id=line.id;
   PERFORM dg_native_dining_effect(action_value,'restaurant_kitchen_tickets',ticket.id);UPDATE restaurant_kitchen_tickets SET pending_cancel_quantity=pending_cancel_quantity-(item->>'quantity')::bigint,version=version+1,updated_at=created WHERE id=ticket.id;
  END LOOP;
  -- Return each original tracked SKU once for trusted, accepted reductions.
  FOR item IN SELECT jsonb_build_object('skuId',value->>'skuId','quantity',sum((value->>'quantity')::bigint)) FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='reduce' AND(value->>'tracked')::boolean GROUP BY value->>'skuId' ORDER BY value->>'skuId' LOOP
   PERFORM dg_native_order_stock_move(action_value,c.id,item->>'skuId',(item->>'quantity')::bigint,'cancel_return');changed:=true;
  END LOOP;
  IF changed THEN PERFORM dg_native_dining_effect(action_value,'restaurants',o.restaurant_id);UPDATE restaurants SET menu_version=menu_version+1,updated_at=created WHERE id=o.restaurant_id;END IF;
  FOR item IN SELECT * FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='add' LOOP
   PERFORM dg_native_dining_effect(action_value,'restaurant_order_lines',item->>'lineId');INSERT INTO restaurant_order_lines(id,order_id,change_id,item_id,sku_id,item_name,sku_name,unit_price_minor,quantity,preparation_note,dietary_tags,stock_tracked,created_at) VALUES(item->>'lineId',o.id,c.id,item->>'itemId',item->>'skuId',item->>'itemName',item->>'skuName',(item->>'unitPriceMinor')::bigint,(item->>'quantity')::bigint,item->>'preparationNote',(item->'dietaryTags')::text,CASE WHEN(item->>'tracked')::boolean THEN 1 ELSE 0 END,created);
   INSERT INTO _dg_native_order_line_origins VALUES(item->>'lineId',c.id,event_value,q.id,dg_native_office_hash(item),(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1));
   ticket_value:=gen_random_uuid()::text;PERFORM dg_native_dining_effect(action_value,'restaurant_kitchen_tickets',ticket_value);INSERT INTO restaurant_kitchen_tickets(id,restaurant_id,order_id,line_id,table_id,table_name,table_code,accepted_at,updated_at) VALUES(ticket_value,o.restaurant_id,o.id,item->>'lineId',snapshot->>'tableId',snapshot->>'tableName',snapshot->>'tableCode',created,created);INSERT INTO _dg_native_order_kitchen_origins VALUES(ticket_value,item->>'lineId',event_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1));
  END LOOP;
  SELECT coalesce(sum((quantity-cancelled_quantity)*unit_price_minor),0) INTO current_total FROM restaurant_order_lines WHERE order_id=o.id;IF current_total<>(snapshot->>'newTotalMinor')::bigint THEN PERFORM dg_native_order_error('ORDER_AMOUNT_INVALID');END IF;
 ELSE PERFORM dg_native_order_inventory(action_value,c.id,q.id,false);END IF;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_quotes',q.id);UPDATE restaurant_order_quotes SET status=status_value WHERE id=q.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_changes',c.id);UPDATE restaurant_order_changes SET status=status_value,version=version+1,updated_at=created WHERE id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET status=status_value,last_sequence=(receipt->>'sequence')::bigint,remote_request_id=receipt->>'remoteRequestId',remote_order_id=receipt->>'remoteOrderId',lease_token=NULL,lease_until=NULL,query_requested=0,error_code=CASE WHEN status_value='rejected' THEN 'POS_REJECTED' END,error_message=CASE WHEN status_value='rejected' THEN '模拟后厨明确拒绝本次变更，预占已释放。' END,version=version+1,updated_at=created WHERE change_id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET pending_change_id=NULL,content_version=content_version+CASE WHEN status_value='accepted' THEN 1 ELSE 0 END,remote_order_id=CASE WHEN status_value='accepted' THEN receipt->>'remoteOrderId' ELSE remote_order_id END,status=CASE WHEN NOT EXISTS(SELECT 1 FROM restaurant_order_lines WHERE order_id=o.id AND quantity>cancelled_quantity) THEN CASE WHEN EXISTS(SELECT 1 FROM restaurant_order_lines WHERE order_id=o.id) THEN 'cancelled' ELSE 'draft' END ELSE 'accepted' END,attention_reason=NULL,version=version+1,updated_at=created WHERE id=o.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_pos_callbacks',event_value);UPDATE restaurant_pos_callbacks SET applied=1 WHERE event_id=event_value;PERFORM dg_native_order_event(action_value,o.id,c.id,'order_receipt',CASE WHEN status_value='accepted' THEN '模拟后厨已确认，价格快照和制作项目已持久保存，尚未结算。' ELSE '模拟后厨明确拒绝此次变更，原已接单内容保留。' END);
END;$dg$;

CREATE FUNCTION dg_native_order_receipt_apply(event_value text,receipt jsonb,ingress_value text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE d restaurant_order_dispatches%ROWTYPE;c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;previous restaurant_pos_callbacks%ROWTYPE;payload_hash_value text;action_value text;created text;status_value text:=receipt->>'status';sequence_value bigint;request jsonb;failure_code text;failure_context text;
BEGIN
 PERFORM dg_native_reception_runtime(true);PERFORM dg_native_restaurant_fields(receipt,ARRAY['requestId','requestHash','restaurantId','remoteRequestId','remoteOrderId','status','sequence','simulated','reasonCode']);sequence_value:=dg_native_restaurant_integer(receipt->'sequence',1,9007199254740991);
 IF event_value IS NULL OR event_value!~'^[a-f0-9-]{36}$' OR ingress_value NOT IN('worker','callback') OR status_value NOT IN('submitted','accepted','rejected') OR receipt->'simulated' IS DISTINCT FROM 'true'::jsonb THEN PERFORM dg_native_order_error('VALIDATION_FAILED');END IF;
 PERFORM dg_native_order_transport_lock(receipt->>'requestId');SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=receipt->>'requestId';SELECT * INTO c FROM restaurant_order_changes WHERE id=d.change_id;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id;request:=d.request_payload::jsonb;
 IF d.change_id IS NULL OR d.request_hash IS DISTINCT FROM receipt->>'requestHash' OR d.restaurant_id IS DISTINCT FROM receipt->>'restaurantId' OR d.provider_id<>'mock-pos' OR d.simulated<>1 OR receipt->>'remoteRequestId' IS DISTINCT FROM 'mock-pos:'||d.change_id OR receipt->>'remoteOrderId' IS DISTINCT FROM coalesce(request->>'remoteOrderId','mock-order:'||o.id) THEN PERFORM dg_native_order_error('POS_RECEIPT_MISMATCH');END IF;
 IF d.attempts<>1 THEN PERFORM dg_native_order_error('POS_REQUEST_NOT_SENT');END IF;
 payload_hash_value:=dg_native_office_hash(jsonb_build_object('eventId',event_value,'receipt',receipt));SELECT * INTO previous FROM restaurant_pos_callbacks WHERE event_id=event_value;
 IF previous.event_id IS NOT NULL THEN IF previous.payload_hash<>payload_hash_value THEN PERFORM dg_native_order_error('POS_EVENT_CONFLICT');END IF;RETURN jsonb_build_object('duplicate',true,'applied',previous.applied=1,'conflict',previous.conflict=1);END IF;
 action_value:=dg_native_order_transport_action(c.id,'order_receipt');SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_pos_callbacks',event_value);INSERT INTO restaurant_pos_callbacks VALUES(event_value,c.id,payload_hash_value,receipt::text,status_value,sequence_value,0,0,created);INSERT INTO _dg_native_order_receipt_origins VALUES(event_value,action_value,(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1),d.request_hash,dg_native_office_hash(receipt),ingress_value,created);
 IF d.status IN('accepted','rejected') THEN
  IF status_value IN('accepted','rejected') AND status_value<>d.status THEN RETURN dg_native_order_receipt_conflict(c.id,event_value,action_value);END IF;
  IF status_value=d.status AND sequence_value>d.last_sequence THEN PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET last_sequence=sequence_value,version=version+1,updated_at=created WHERE change_id=c.id;END IF;RETURN jsonb_build_object('duplicate',false,'applied',false,'conflict',false);
 END IF;
 IF d.error_code='POS_RECONCILIATION_REQUIRED' OR d.status NOT IN('submitting','submitted','unknown') THEN RETURN dg_native_order_receipt_conflict(c.id,event_value,action_value);END IF;
 IF sequence_value<=d.last_sequence THEN
  IF status_value IN('accepted','rejected') THEN RETURN dg_native_order_receipt_conflict(c.id,event_value,action_value);END IF;RETURN jsonb_build_object('duplicate',false,'applied',false,'conflict',false);
 END IF;
 IF status_value='submitted' THEN
  PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET status='submitted',last_sequence=sequence_value,remote_request_id=receipt->>'remoteRequestId',remote_order_id=receipt->>'remoteOrderId',lease_token=NULL,lease_until=NULL,error_code=NULL,error_message=NULL,query_requested=0,version=version+1,updated_at=created WHERE change_id=c.id;PERFORM dg_native_order_transport_state(c.id,action_value,'submitted','模拟渠道已接收原请求，仍等待后厨确认。');UPDATE restaurant_pos_callbacks SET applied=1 WHERE event_id=event_value;RETURN jsonb_build_object('duplicate',false,'applied',true,'conflict',false);
 END IF;
 BEGIN
  PERFORM dg_native_order_receipt_business(c.id,event_value,action_value,status_value,receipt);
  -- Catch deferred business invariant failures before returning success, while
  -- retaining the trusted receipt outside this subtransaction.
  SET CONSTRAINTS ALL IMMEDIATE;SET CONSTRAINTS ALL DEFERRED;
 EXCEPTION WHEN OTHERS THEN
  GET STACKED DIAGNOSTICS failure_code=RETURNED_SQLSTATE,failure_context=PG_EXCEPTION_CONTEXT;
  INSERT INTO _dg_native_order_receipt_failures VALUES(event_value,failure_code,coalesce(substring(failure_context FROM 'PL/pgSQL function [a-z_]+\([^\n]*line [0-9]+'),'business invariant'),created);
  RETURN dg_native_order_receipt_conflict(c.id,event_value,action_value);
 END;
 RETURN jsonb_build_object('duplicate',false,'applied',true,'conflict',false);
END;$dg$;

CREATE FUNCTION dg_native_order_worker_complete(change_value text,lease_value text,receipt jsonb DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE context jsonb;action_value text;created text;mode_value text;
BEGIN
 PERFORM dg_native_order_transport_lock(change_value);context:=dg_native_order_worker_context(change_value,lease_value);
 IF receipt IS NOT NULL THEN IF receipt->>'requestId' IS DISTINCT FROM change_value OR receipt->>'requestHash' IS DISTINCT FROM context->>'requestHash' THEN PERFORM dg_native_order_error('POS_RECEIPT_MISMATCH');END IF;RETURN dg_native_order_receipt_apply(gen_random_uuid()::text,receipt,'worker');END IF;
 action_value:=dg_native_order_transport_action(change_value,'order_unknown');SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',change_value);UPDATE restaurant_order_dispatches SET status='unknown',lease_token=NULL,lease_until=NULL,error_code='POS_RESULT_UNKNOWN',error_message='原请求结果尚未核实，库存与请求保留；仅可查询原请求或联系店员。',query_requested=0,version=version+1,updated_at=created WHERE change_id=change_value;PERFORM dg_native_order_transport_state(change_value,action_value,'unknown','原请求结果未知，未释放库存，也不会自动另发新单。');RETURN jsonb_build_object('duplicate',false,'applied',false,'conflict',false);
END;$dg$;

CREATE FUNCTION dg_native_order_query(target text,input jsonb,session_value text DEFAULT NULL,token_value text DEFAULT NULL,csrf_value text DEFAULT NULL,focus_value bigint DEFAULT NULL) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;d restaurant_order_dispatches%ROWTYPE;c restaurant_order_changes%ROWTYPE;action_value text;created text;body jsonb:=input-ARRAY['focusVersion','selectionVersion'];
BEGIN
 meta:=dg_native_order_context('change',target,session_value,token_value,csrf_value,focus_value,true);PERFORM dg_native_order_input(meta,input);PERFORM dg_native_restaurant_fields(body,ARRAY['version']);SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=target FOR UPDATE;SELECT * INTO c FROM restaurant_order_changes WHERE id=target;
 IF dg_native_restaurant_integer(body->'version',1,9007199254740991) IS DISTINCT FROM d.version THEN PERFORM dg_native_order_error('VERSION_CONFLICT');END IF;
 IF d.status NOT IN('unknown','submitted') OR d.attempts<>1 OR d.error_code='POS_RECONCILIATION_REQUIRED' THEN PERFORM dg_native_order_error('POS_QUERY_UNAVAILABLE');END IF;
 IF(SELECT count(*) FROM _dg_native_dining_actions WHERE kind='order_query' AND resource_id=meta->>'partyId' AND created_at>dg_native_people_iso(clock_timestamp()-interval '1 minute'))>=20 THEN PERFORM dg_native_order_error('RATE_LIMITED');END IF;
 action_value:=dg_native_dining_action(meta,'order_query','party',meta->>'partyId',body);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',d.change_id);UPDATE restaurant_order_dispatches SET query_requested=1,version=version+1,updated_at=created WHERE change_id=d.change_id;PERFORM dg_native_order_event(action_value,c.order_id,c.id,'order_query','已请求查询原远端请求，不会另外发送订单。');INSERT INTO _dg_native_order_results VALUES(action_value,meta->>'restaurantId',c.order_id,c.id,c.confirmed_quote_id,(meta->>'partyAccessVersion')::bigint,created);RETURN action_value;
END;$dg$;

CREATE FUNCTION dg_native_order_mock_fixture(target text,input jsonb) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE meta jsonb;d restaurant_order_dispatches%ROWTYPE;c restaurant_order_changes%ROWTYPE;action_value text;created text;
BEGIN
 meta:=dg_native_order_context('change',target,NULL,NULL,NULL,NULL,true);PERFORM dg_native_restaurant_prepare('restaurant',meta->>'restaurantId',true,true,NULL);PERFORM dg_native_restaurant_fields(input,ARRAY['version','outcome','confirmed']);SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=target FOR UPDATE;SELECT * INTO c FROM restaurant_order_changes WHERE id=target;
 IF dg_native_restaurant_integer(input->'version',1,9007199254740991) IS DISTINCT FROM d.version THEN PERFORM dg_native_order_error('VERSION_CONFLICT');END IF;
 IF input->'confirmed' IS DISTINCT FROM 'true'::jsonb OR input->>'outcome' NOT IN('accepted','rejected') THEN PERFORM dg_native_order_error('VALIDATION_FAILED');END IF;
 IF d.status<>'unknown' OR d.attempts<>1 OR d.provider_id<>'mock-pos' OR d.config_snapshot::jsonb->>'scenario'<>'unresolved' OR d.error_code='POS_RECONCILIATION_REQUIRED' OR EXISTS(SELECT 1 FROM mock_pos_operations WHERE change_id=d.change_id) THEN PERFORM dg_native_order_error('POS_FIXTURE_UNAVAILABLE');END IF;
 action_value:=dg_native_dining_action(meta,'order_mock_fixture','party',meta->>'partyId',input);SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;PERFORM dg_native_order_mock_record(target,input->>'outcome',action_value);PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',target);UPDATE restaurant_order_dispatches SET query_requested=1,version=version+1,updated_at=created WHERE change_id=target;PERFORM dg_native_order_event(action_value,c.order_id,c.id,'order_mock_fixture','经理已明确建立本地模拟远端事实，仍由后台查询原请求后核对接单。');INSERT INTO _dg_native_order_results VALUES(action_value,meta->>'restaurantId',c.order_id,c.id,c.confirmed_quote_id,(meta->>'partyAccessVersion')::bigint,created);RETURN action_value;
END;$dg$;

CREATE FUNCTION dg_native_order_transport_record(table_value text,operation_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE record_value text;order_value text;party_value text;restaurant_value text;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 record_value:=CASE WHEN table_value IN('restaurant_order_dispatches','mock_pos_operations') THEN j->>'change_id' WHEN table_value='restaurant_pos_callbacks' THEN j->>'event_id' ELSE j->>'id' END;
 IF table_value='restaurant_orders' THEN order_value:=j->>'id';ELSIF table_value IN('restaurant_order_changes','restaurant_order_lines','restaurant_kitchen_tickets','restaurant_order_events') THEN order_value:=j->>'order_id';ELSE SELECT order_id INTO order_value FROM restaurant_order_changes WHERE id=j->>'change_id';END IF;
 SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 SELECT a.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.restaurant_id=restaurant_value AND a.resource_id=party_value AND a.kind IN('order_send','order_lookup','order_unknown','order_receipt','order_query','order_mock_fixture','order_mock_remote') ORDER BY a.created_at DESC,a.id DESC LIMIT 1;
 IF action.id IS NULL THEN RETURN false;END IF;IF operation_value='DELETE' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch and trusted business facts cannot be deleted';END IF;
 IF table_value='restaurant_orders' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','content_version','pending_change_id','remote_order_id','control_mode','attention_reason','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j->>'status' NOT IN('submitting','submitted','needs_attention','accepted','draft','cancelled') OR j->>'settlement_status'<>'unsettled' OR(j->>'content_version')::bigint NOT BETWEEN(previous->>'content_version')::bigint AND(previous->>'content_version')::bigint+1 OR action.kind<>'order_receipt' AND j-ARRAY['status','version','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','updated_at'] OR action.kind='order_receipt' AND j->>'remote_order_id' IS DISTINCT FROM previous->>'remote_order_id' AND previous->>'remote_order_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport only changes order state or applies the original trusted content once';END IF;
 ELSIF table_value='restaurant_order_changes' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['version','status','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting' OR action.kind='order_lookup' AND previous->>'status'='submitting' AND j->>'status'='unknown' OR action.kind='order_unknown' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status'='unknown' OR action.kind='order_receipt' AND previous->>'status' IN('submitting','submitted','unknown') AND j->>'status' IN('submitted','accepted','rejected','unknown')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport cannot rewrite draft identity, input or its original confirmation';END IF;
 ELSIF table_value='restaurant_order_dispatches' THEN
  IF operation_value<>'UPDATE' OR j-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','attempts','lease_token','lease_until','remote_request_id','remote_order_id','last_sequence','error_code','error_message','query_requested','lookups','last_lookup_at','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'attempts')::bigint<>1 OR j->>'status' NOT IN('submitting','submitted','unknown','accepted','rejected') OR(j->>'last_sequence')::bigint<(previous->>'last_sequence')::bigint OR(previous->>'attempts')::bigint=0 AND NOT(action.kind='order_send' AND previous->>'status'='queued' AND j->>'status'='submitting') OR previous->>'status' IN('accepted','rejected') AND j->>'status' IS DISTINCT FROM previous->>'status' OR action.kind IN('order_query','order_mock_fixture') AND j-ARRAY['version','query_requested','updated_at'] IS DISTINCT FROM previous-ARRAY['version','query_requested','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch attempts and the frozen original request cannot be reset or retargeted';END IF;
 ELSIF table_value='restaurant_order_quotes' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'current' OR j->>'status' NOT IN('accepted','rejected') OR j-'status' IS DISTINCT FROM previous-'status' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Final receipts consume the original quote without changing its deadline or contents';END IF;
 ELSIF table_value='restaurant_inventory_reservations' THEN
  IF operation_value<>'UPDATE' OR action.kind<>'order_receipt' OR previous->>'status'<>'reserved' OR j->>'status' NOT IN('committed','released') OR j-ARRAY['status','updated_at'] IS DISTINCT FROM previous-ARRAY['status','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only trusted final receipts commit or release existing reservations';END IF;
 ELSIF table_value='restaurant_stock_movements' THEN
  IF operation_value<>'INSERT' OR action.kind<>'order_receipt' OR j->>'kind' NOT IN('release','cancel_return') OR(j->>'after_quantity')::bigint<=(j->>'before_quantity')::bigint THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stock returns require the trusted original receipt';END IF;
 ELSIF table_value='restaurant_order_lines' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'cancelled_quantity')::bigint<>0 OR j->>'created_at'<>action.created_at) OR operation_value='UPDATE' AND(j-'cancelled_quantity' IS DISTINCT FROM previous-'cancelled_quantity' OR(j->>'cancelled_quantity')::bigint<=(previous->>'cancelled_quantity')::bigint OR(j->>'cancelled_quantity')::bigint>(j->>'quantity')::bigint)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted line snapshots are immutable except trusted cancelled quantities';END IF;
 ELSIF table_value='restaurant_kitchen_tickets' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND((j->>'started_quantity')::bigint<>0 OR(j->>'ready_quantity')::bigint<>0 OR(j->>'served_quantity')::bigint<>0 OR(j->>'pending_cancel_quantity')::bigint<>0 OR(j->>'version')::bigint<>1 OR j->>'accepted_at'<>action.created_at) OR operation_value='UPDATE' AND(j-ARRAY['pending_cancel_quantity','version','updated_at'] IS DISTINCT FROM previous-ARRAY['pending_cancel_quantity','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'pending_cancel_quantity')::bigint<0)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt creates original kitchen rows without inventing preparation progress';END IF;
 ELSIF table_value='restaurant_pos_callbacks' THEN
  IF action.kind<>'order_receipt' OR(operation_value='INSERT' AND(j->>'created_at'<>action.created_at OR j->>'applied'<>'0' OR j->>'conflict'<>'0') OR operation_value='UPDATE' AND(j-ARRAY['applied','conflict'] IS DISTINCT FROM previous-ARRAY['applied','conflict'] OR previous->>'applied'<>'0' OR previous->>'conflict'<>'0' OR(j->>'applied')::bigint+(j->>'conflict')::bigint<>1)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Receipt payload is immutable and has one terminal local application outcome';END IF;
 ELSIF table_value='mock_pos_operations' THEN
  IF operation_value<>'INSERT' OR action.kind NOT IN('order_mock_remote','order_mock_fixture') OR j->>'outcome' NOT IN('accepted','rejected') OR j->>'sequence'<>'2' OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Explicit local mock facts are append-only and cannot replace a real provider';END IF;
 ELSIF table_value='restaurant_order_events' THEN
  IF operation_value<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Transport audit retains its actual operation and actor';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported transport effect';END IF;RETURN true;
END;$dg$;

CREATE OR REPLACE FUNCTION dg_native_order_transport_source_reason(change_value text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;d restaurant_order_dispatches%ROWTYPE;q restaurant_order_quotes%ROWTYPE;origin _dg_native_order_quote_origins%ROWTYPE;p dining_parties%ROWTYPE;r restaurants%ROWTYPE;seat dining_occupancies%ROWTYPE;t restaurant_tables%ROWTYPE;config restaurant_pos_configs%ROWTYPE;snapshot jsonb;pref jsonb;
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id;SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=c.id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;SELECT * INTO origin FROM _dg_native_order_quote_origins WHERE quote_id=q.id;snapshot:=q.payload::jsonb;
 IF q.id IS NULL OR origin.quote_id IS NULL OR q.status<>'current' OR q.expires_at<=dg_native_dining_now() THEN RETURN '原确认期限已到，未发送请求需要重新审阅。';END IF;
 IF c.status<>'submitting' OR d.status<>'submitting' OR d.attempts<>1 OR o.pending_change_id IS DISTINCT FROM c.id THEN RETURN '此请求已进入发送或核对流程，不能当作未发送处理。';END IF;
 SELECT * INTO p FROM dining_parties WHERE id=o.party_id;SELECT * INTO r FROM restaurants WHERE id=o.restaurant_id;SELECT * INTO seat FROM dining_occupancies WHERE party_id=p.id AND state='seated';SELECT * INTO t FROM restaurant_tables WHERE id=seat.table_id;SELECT * INTO config FROM restaurant_pos_configs WHERE restaurant_id=r.id;pref:=dg_native_food_preference(p.id,origin.actor_meta);
 IF NOT dg_native_order_source(origin.actor_meta,p.id) OR p.version<>(snapshot->>'partyVersion')::bigint OR p.status<>'seated' OR o.control_mode<>'automatic' OR o.settlement_status<>'unsettled' OR o.content_version<>(snapshot->>'contentVersion')::bigint THEN RETURN '发送前服务对象、就餐归属或控制状态已变化。';END IF;
 IF seat.id IS DISTINCT FROM snapshot->>'occupancyId' OR t.id IS DISTINCT FROM snapshot->>'tableId' OR t.version<>(snapshot->>'tableVersion')::bigint OR t.enabled<>1 OR t.operation<>'open' OR r.version<>(snapshot->>'restaurantVersion')::bigint THEN RETURN '发送前桌位或门店配置已变化。';END IF;
 IF pref IS NULL OR pref->'usable' IS DISTINCT FROM 'true'::jsonb OR dg_native_office_hash(pref)<>snapshot->>'preferenceHash' THEN RETURN '发送前偏好或来源授权已变化。';END IF;
 IF config.restaurant_id IS NULL OR config.enabled<>1 OR config.version<>d.config_version OR config.provider_id<>d.provider_id OR config.provider_id<>'mock-pos' THEN RETURN '发送前后厨连接已变化。';END IF;
 -- Current menu/stock versions can change through our own reservation; the
 -- submitted immutable price and allocated quantities remain authoritative.
 RETURN NULL;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_record_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);previous jsonb:=to_jsonb(OLD);record_value text;restaurant_value text;party_value text;order_value text;action _dg_native_dining_actions%ROWTYPE;
BEGIN
 IF dg_native_order_transport_record(TG_TABLE_NAME,TG_OP,j,previous) THEN RETURN NEW;END IF;
 record_value:=CASE TG_TABLE_NAME WHEN 'restaurant_pos_configs' THEN j->>'restaurant_id' WHEN 'restaurant_order_dispatches' THEN j->>'change_id' ELSE j->>'id' END;
 IF TG_OP='DELETE' OR NOT dg_native_dining_changed(TG_TABLE_NAME,record_value) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native order records require their actual scoped operation';END IF;
 IF TG_TABLE_NAME='restaurant_pos_configs' THEN restaurant_value:=j->>'restaurant_id';
 ELSIF TG_TABLE_NAME='restaurant_orders' THEN restaurant_value:=j->>'restaurant_id';party_value:=j->>'party_id';
 ELSE
  order_value:=CASE WHEN TG_TABLE_NAME='restaurant_order_changes' OR TG_TABLE_NAME='restaurant_order_events' OR TG_TABLE_NAME='restaurant_kitchen_tickets' THEN j->>'order_id' ELSE(SELECT c.order_id FROM restaurant_order_changes c WHERE c.id=j->>'change_id') END;
  SELECT restaurant_id,party_id INTO restaurant_value,party_value FROM restaurant_orders WHERE id=order_value;
 END IF;
 SELECT a.* INTO action FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=TG_TABLE_NAME AND effect.resource_id=record_value AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.restaurant_id=restaurant_value AND a.resource_id=coalesce(party_value,restaurant_value) AND a.kind IN('order_config','order_draft','order_update','order_review','order_confirm','order_submit','order_withdraw','order_expire','order_quote_expire') ORDER BY a.created_at DESC,a.id DESC LIMIT 1;
 IF action.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order effects cannot borrow unrelated business actions';END IF;
 IF TG_TABLE_NAME='restaurant_orders' THEN
  IF j->>'control_mode'<>'automatic' OR j->>'settlement_status'<>'unsettled' OR j->>'attention_reason' IS NOT NULL OR(TG_OP='INSERT' AND(j->>'remote_order_id' IS NOT NULL OR(j->>'content_version')::bigint<>1)) OR j->>'status' NOT IN('draft','awaiting_confirmation','confirmed','queued','cancelled','accepted') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='This order stage cannot fabricate acceptance, payment or remote facts';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_draft' OR j->>'status'<>'draft' OR(j->>'version')::bigint<>1 OR j->>'pending_change_id' IS NOT NULL OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native order creation is an unsubmitted original draft';END IF;
  ELSIF j-ARRAY['version','status','pending_change_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','pending_change_id','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR previous->>'status' IN('closed','cancelled') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order identity, accepted content and terminal states cannot be rewritten';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_changes' THEN
  IF j->>'source'<>'manual' OR j->>'source_request_id' IS NOT NULL OR j->>'kind' NOT IN('initial','amend','cancel') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Drafts cannot claim a fabricated conversation or source';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_draft' OR j->>'status'<>'draft' OR(j->>'version')::bigint<>1 OR j->>'created_at'<>action.created_at OR j->>'confirmed_at' IS NOT NULL OR j->>'current_quote_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order changes start as the next editable draft';END IF;
  ELSE
   IF j-ARRAY['version','status','input','base_content_version','actor_id','session_id','focus_version','party_access_version','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','input','base_content_version','actor_id','session_id','focus_version','party_access_version','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Change scope, sequence, source and version are immutable';END IF;
   IF NOT(action.kind='order_update' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed') AND j->>'status'='draft' OR action.kind='order_review' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed') AND j->>'status'='awaiting_confirmation' OR action.kind='order_confirm' AND previous->>'status'='awaiting_confirmation' AND j->>'status'='confirmed' OR action.kind='order_submit' AND previous->>'status'='confirmed' AND j->>'status'='queued' OR action.kind='order_withdraw' AND previous->>'status' IN('draft','awaiting_confirmation','confirmed','queued','rejected','stale') AND j->>'status'='withdrawn' OR action.kind='order_expire' AND previous->>'status'='queued' AND j->>'status'='stale') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Unsupported order change transition';END IF;
   IF action.kind<>'order_update' AND j-ARRAY['version','status','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] IS DISTINCT FROM previous-ARRAY['version','status','current_quote_id','confirmed_at','confirmed_actor_id','confirmed_focus_version','confirmed_quote_id','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Review, confirmation and dispatch cannot rewrite draft input or attribution';END IF;
  END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_quotes' THEN
  IF TG_OP='INSERT' THEN IF action.kind<>'order_review' OR j->>'status'<>'current' OR j->>'created_at'<>action.created_at OR(j->>'expires_at')::timestamptz<>(j->>'created_at')::timestamptz+interval '120 seconds' THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quotes keep a fixed original two-minute deadline';END IF;
  ELSIF j-'status' IS DISTINCT FROM previous-'status' OR previous->>'status'<>'current' OR j->>'status' NOT IN('superseded','withdrawn','expired') OR j->>'status'='expired' AND j->>'expires_at'>dg_native_dining_now() THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote content, attribution and original deadline cannot be replaced';END IF;
 ELSIF TG_TABLE_NAME='restaurant_pos_configs' THEN
  IF action.kind<>'order_config' OR j->>'provider_id' NOT IN('mock-pos','external-pos') OR(j->>'enabled')::bigint NOT IN(0,1) OR j->>'provider_id'='external-pos' AND j->>'enabled'<>'0' OR j->>'scenario' NOT IN('normal','rejected','response_lost','unresolved') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Native POS configuration cannot silently simulate a live provider';END IF;
  IF TG_OP='INSERT' THEN IF(j->>'version')::bigint<>1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS config starts at version one';END IF;
  ELSIF j-ARRAY['provider_id','enabled','scenario','version','updated_at'] IS DISTINCT FROM previous-ARRAY['provider_id','enabled','scenario','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS config versions and original creation are guarded';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_dispatches' THEN
  IF TG_OP='INSERT' THEN IF action.kind<>'order_submit' OR j->>'status'<>'queued' OR j->>'attempts'<>'0' OR j->>'version'<>'1' OR j->>'simulated'<>'1' OR j->>'provider_id'<>'mock-pos' OR j->>'lease_token' IS NOT NULL OR j->>'lease_until' IS NOT NULL OR j->>'remote_request_id' IS NOT NULL OR j->>'remote_order_id' IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A persistent dispatch is queued and has not claimed external success';END IF;
  ELSIF action.kind NOT IN('order_withdraw','order_expire') OR previous->>'status'<>'queued' OR previous->>'attempts'<>'0' OR j->>'status'<>'cancelled' OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR j-ARRAY['status','version','error_code','error_message','updated_at'] IS DISTINCT FROM previous-ARRAY['status','version','error_code','error_message','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only definitely unsent dispatches can be withdrawn in this stage';END IF;
 ELSIF TG_TABLE_NAME='restaurant_inventory_reservations' THEN
  IF(j->>'quantity')::bigint<=0 OR j->>'tracked' NOT IN('0','1') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Inventory reservation quantities are positive and explicitly tracked';END IF;
  IF TG_OP='INSERT' THEN IF action.kind<>'order_submit' OR j->>'status'<>'reserved' OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Reservations originate in the atomic submit';END IF;
  ELSIF action.kind NOT IN('order_withdraw','order_expire') OR previous->>'status'<>'reserved' OR j->>'status'<>'released' OR j-ARRAY['status','updated_at'] IS DISTINCT FROM previous-ARRAY['status','updated_at'] THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Only original reservations can be released once';END IF;
 ELSIF TG_TABLE_NAME='restaurant_stock_movements' THEN
  IF TG_OP<>'INSERT' OR j->>'kind' NOT IN('reserve','release') OR(j->>'before_quantity')::bigint<0 OR(j->>'after_quantity')::bigint<0 OR NOT(action.kind='order_submit' AND j->>'kind'='reserve' AND(j->>'before_quantity')::bigint>(j->>'after_quantity')::bigint OR action.kind IN('order_withdraw','order_expire') AND j->>'kind'='release' AND(j->>'before_quantity')::bigint<(j->>'after_quantity')::bigint) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Stock movements are append-only actual reservation or release deltas';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_events' THEN
  IF TG_OP<>'INSERT' OR j->>'actor_id'<>action.actor_id OR j->>'kind'<>action.kind OR j->>'created_at'<>action.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order events retain their actual operation and actor';END IF;
 ELSE
  IF TG_TABLE_NAME<>'restaurant_kitchen_tickets' OR TG_OP<>'UPDATE' OR action.kind NOT IN('order_submit','order_withdraw','order_expire') OR j-ARRAY['pending_cancel_quantity','version','updated_at'] IS DISTINCT FROM previous-ARRAY['pending_cancel_quantity','version','updated_at'] OR(j->>'version')::bigint<>(previous->>'version')::bigint+1 OR(j->>'pending_cancel_quantity')::bigint<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='This stage cannot fabricate kitchen progress';END IF;
 END IF;RETURN NEW;
END;$dg$;


CREATE TRIGGER native_order_transport_record BEFORE INSERT OR UPDATE OR DELETE ON restaurant_order_lines FOR EACH ROW EXECUTE FUNCTION dg_native_order_record_guard();

CREATE TRIGGER native_order_transport_record BEFORE INSERT OR UPDATE OR DELETE ON restaurant_pos_callbacks FOR EACH ROW EXECUTE FUNCTION dg_native_order_record_guard();

CREATE TRIGGER native_order_transport_record BEFORE INSERT OR UPDATE OR DELETE ON mock_pos_operations FOR EACH ROW EXECUTE FUNCTION dg_native_order_record_guard();

CREATE OR REPLACE FUNCTION dg_native_order_stock_move(action_value text,change_value text,sku_value text,delta_value bigint,kind_value text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE sku restaurant_menu_skus%ROWTYPE;movement_value text:=gen_random_uuid()::text;created text;
BEGIN
 SELECT * INTO sku FROM restaurant_menu_skus WHERE id=sku_value FOR UPDATE;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 IF sku.id IS NULL OR sku.stock_remaining+delta_value NOT BETWEEN 0 AND 1000000 OR(kind_value='reserve' AND delta_value>=0) OR(kind_value IN('release','cancel_return') AND delta_value<=0) OR kind_value NOT IN('reserve','release','cancel_return') THEN PERFORM dg_native_order_error('ORDER_STOCK_CHANGED');END IF;
 PERFORM dg_native_dining_effect(action_value,'restaurant_stock_movements',movement_value);INSERT INTO restaurant_stock_movements VALUES(movement_value,sku.restaurant_id,sku.id,change_value,kind_value,sku.stock_remaining,sku.stock_remaining+delta_value,created);
 PERFORM dg_native_dining_effect(action_value,'restaurant_menu_skus',sku.id);UPDATE restaurant_menu_skus SET stock_remaining=stock_remaining+delta_value,version=version+1 WHERE id=sku.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_menu_items',sku.item_id);UPDATE restaurant_menu_items SET version=version+1 WHERE id=sku.item_id;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_catalog_guard(table_value text,j jsonb,previous jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE kinds text[];
BEGIN
 SELECT array_agg(a.kind) INTO kinds FROM _dg_native_dining_changes effect JOIN _dg_native_dining_actions a ON a.id=effect.action_id WHERE effect.table_name=table_value AND effect.resource_id=j->>'id' AND effect.transaction_id=pg_current_xact_id()::text AND a.transaction_id=effect.transaction_id AND a.kind IN('order_draft','order_submit','order_withdraw','order_expire','order_receipt');IF kinds IS NULL THEN RETURN false;END IF;
 IF table_value='restaurants' AND 'order_draft'=ANY(kinds) AND j-'order_counter'=previous-'order_counter' AND(j->>'order_counter')::numeric=(previous->>'order_counter')::numeric+1 AND(j->>'order_counter')::numeric<=9007199254740991 THEN RETURN true;END IF;
 IF NOT kinds&&ARRAY['order_submit','order_withdraw','order_expire','order_receipt'] THEN RETURN false;END IF;
 IF table_value='restaurants' AND j-ARRAY['menu_version','updated_at']=previous-ARRAY['menu_version','updated_at'] AND(j->>'menu_version')::bigint=(previous->>'menu_version')::bigint+1 THEN RETURN true;END IF;
 IF table_value='restaurant_menu_skus' AND j-ARRAY['stock_remaining','version']=previous-ARRAY['stock_remaining','version'] AND(j->>'version')::bigint=(previous->>'version')::bigint+1 AND(j->>'stock_remaining')::bigint BETWEEN 0 AND 1000000 THEN RETURN true;END IF;
 IF table_value='restaurant_menu_items' AND j-ARRAY['version','updated_at']=previous-ARRAY['version','updated_at'] AND(j->>'version')::bigint=(previous->>'version')::bigint+1 THEN RETURN true;END IF;RETURN false;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);order_value text;o restaurant_orders%ROWTYPE;c restaurant_order_changes%ROWTYPE;q restaurant_order_quotes%ROWTYPE;d restaurant_order_dispatches%ROWTYPE;origin _dg_native_order_quote_origins%ROWTYPE;config restaurant_pos_configs%ROWTYPE;hold restaurant_inventory_reservations%ROWTYPE;payload jsonb;expected_quantity bigint;
BEGIN
 IF TG_TABLE_NAME='restaurant_pos_configs' THEN
  SELECT * INTO config FROM restaurant_pos_configs WHERE restaurant_id=j->>'restaurant_id';
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_pos_revisions revision JOIN _dg_native_dining_actions action ON action.id=revision.action_id WHERE revision.restaurant_id=config.restaurant_id AND revision.version=config.version AND revision.provider_id=config.provider_id AND revision.enabled=config.enabled AND revision.scenario=config.scenario AND action.kind='order_config' AND action.resource_id=config.restaurant_id AND action.created_at=config.updated_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='POS configuration requires its immutable current revision';END IF;RETURN NULL;
 END IF;
 IF TG_TABLE_NAME='restaurant_orders' THEN order_value:=j->>'id';
 ELSIF TG_TABLE_NAME='restaurant_order_changes' THEN order_value:=j->>'order_id';
 ELSE SELECT change.order_id INTO order_value FROM restaurant_order_changes change WHERE change.id=j->>'change_id';END IF;
 SELECT current_order.* INTO o FROM restaurant_orders current_order JOIN _dg_native_order_origins fixed ON fixed.order_id=current_order.id JOIN _dg_native_dining_actions action ON action.id=fixed.action_id JOIN dining_parties party ON party.id=fixed.party_id WHERE current_order.id=order_value AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.party_id=current_order.party_id AND current_order.restaurant_id=party.restaurant_id AND fixed.created_at=current_order.created_at AND action.created_at=fixed.created_at AND action.kind='order_draft' AND action.resource_id=party.id;
 IF o.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Order and party require their original scoped creation';END IF;
 IF o.pending_change_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM restaurant_order_changes pending WHERE pending.id=o.pending_change_id AND pending.order_id=o.id AND (pending.status=o.status OR pending.status='unknown' AND o.status='needs_attention') AND pending.status IN('draft','awaiting_confirmation','confirmed','queued','submitting','submitted','unknown')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Pending order state must match its current change';END IF;
 IF TG_TABLE_NAME='restaurant_order_changes' THEN
  SELECT * INTO c FROM restaurant_order_changes WHERE id=j->>'id';
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_change_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.change_id=c.id AND fixed.order_id=o.id AND fixed.party_id=o.party_id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.created_at=c.created_at AND action.created_at=fixed.created_at AND action.kind='order_draft' AND action.resource_id=o.party_id) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_change_revisions revision WHERE revision.change_id=c.id AND revision.version=c.version AND revision.row_hash=dg_native_office_hash(to_jsonb(c))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Changes retain their origin and exact immutable latest revision';END IF;
  IF c.status IN('awaiting_confirmation','confirmed','queued','submitting','submitted','unknown','accepted','rejected') AND NOT EXISTS(SELECT 1 FROM restaurant_order_quotes quote WHERE quote.id=c.current_quote_id AND quote.change_id=c.id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A reviewed change requires its original quote';END IF;
  IF c.status IN('confirmed','queued','submitting','submitted','unknown','accepted','rejected') AND(c.confirmed_at IS NULL OR c.confirmed_actor_id IS NULL OR c.confirmed_quote_id IS DISTINCT FROM c.current_quote_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Confirmed changes retain their actual explicit confirmation';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_quotes' THEN
  SELECT * INTO q FROM restaurant_order_quotes WHERE id=j->>'id';SELECT * INTO origin FROM _dg_native_order_quote_origins WHERE quote_id=q.id;SELECT * INTO c FROM restaurant_order_changes WHERE id=q.change_id;payload:=q.payload::jsonb;
  IF origin.quote_id IS NULL OR origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR origin.payload_hash<>q.hash OR q.hash<>dg_native_office_hash(payload) OR origin.created_at<>q.created_at OR origin.expires_at<>q.expires_at OR payload->>'id'<>q.id OR payload->>'changeId'<>c.id OR payload->>'orderId'<>o.id OR payload->>'restaurantId'<>o.restaurant_id OR payload->>'partyId'<>o.party_id OR payload->>'expiresAt'<>q.expires_at OR origin.actor_meta->>'actorId' IS DISTINCT FROM q.actor_id OR origin.actor_meta->>'sessionId' IS DISTINCT FROM q.session_id OR(origin.actor_meta->>'focusVersion')::bigint IS DISTINCT FROM q.focus_version OR NOT EXISTS(SELECT 1 FROM _dg_native_dining_actions action WHERE action.id=origin.action_id AND action.kind='order_review' AND action.resource_id=o.party_id AND action.created_at=q.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Quote payload, actor, hash and original deadline require the same review';END IF;
  IF EXISTS(SELECT 1 FROM _dg_native_dining_actions action WHERE action.id=origin.action_id AND action.transaction_id=pg_current_xact_id()::text) AND(q.expires_at<=dg_native_dining_now() OR NOT dg_native_order_source(origin.actor_meta,o.party_id)) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='A new quote cannot commit with an expired source';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_dispatches' THEN
  SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=j->>'change_id';SELECT * INTO c FROM restaurant_order_changes WHERE id=d.change_id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;payload:=d.request_payload::jsonb;
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_dispatch_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.change_id=d.change_id AND fixed.quote_id=q.id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.request_hash=d.request_hash AND action.kind='order_submit' AND action.resource_id=o.party_id AND action.created_at=d.created_at AND fixed.created_at=d.created_at) OR d.request_hash<>dg_native_office_hash(payload) OR d.restaurant_id<>o.restaurant_id OR payload->>'requestId'<>c.id OR payload->>'orderId'<>o.id OR payload->>'restaurantId'<>o.restaurant_id OR(d.config_snapshot::jsonb->>'version')::bigint<>d.config_version OR d.config_snapshot::jsonb->>'provider_id'<>d.provider_id OR d.status='queued' AND(c.status<>'queued' OR o.pending_change_id IS DISTINCT FROM c.id) OR d.status='cancelled' AND c.status NOT IN('withdrawn','stale') THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch is the original confirmed atomic request and matching state';END IF;
  IF EXISTS(SELECT 1 FROM(SELECT value->>'skuId' sku_id,sum((value->>'quantity')::bigint) quantity FROM jsonb_array_elements(q.payload::jsonb->'lines') WHERE value->>'operation'='add' GROUP BY value->>'skuId') totals WHERE NOT EXISTS(SELECT 1 FROM restaurant_inventory_reservations reservation JOIN _dg_native_order_reservation_origins fixed ON fixed.reservation_id=reservation.id WHERE reservation.change_id=c.id AND reservation.sku_id=totals.sku_id AND reservation.quantity=totals.quantity AND reservation.status=(CASE WHEN d.status IN('queued','submitting','submitted','unknown') THEN 'reserved' WHEN d.status='accepted' THEN 'committed' ELSE 'released' END))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Every submitted add has the exact aggregated atomic reservation';END IF;
 ELSIF TG_TABLE_NAME='restaurant_inventory_reservations' THEN
  SELECT * INTO hold FROM restaurant_inventory_reservations WHERE id=j->>'id';SELECT * INTO c FROM restaurant_order_changes WHERE id=hold.change_id;SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=c.id;SELECT * INTO q FROM restaurant_order_quotes WHERE id=c.confirmed_quote_id;
  SELECT sum((value->>'quantity')::bigint) INTO expected_quantity FROM jsonb_array_elements(q.payload::jsonb->'lines') WHERE value->>'operation'='add' AND value->>'skuId'=hold.sku_id;
  IF hold.quantity IS DISTINCT FROM expected_quantity OR d.change_id IS NULL OR hold.status IS DISTINCT FROM(CASE WHEN d.status IN('queued','submitting','submitted','unknown') THEN 'reserved' WHEN d.status='accepted' THEN 'committed' ELSE 'released' END) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_reservation_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.reservation_id=hold.id AND fixed.change_id=c.id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND action.kind='order_submit' AND action.resource_id=o.party_id AND fixed.created_at=hold.created_at AND action.created_at=hold.created_at) OR(hold.tracked=1) IS DISTINCT FROM(SELECT bool_and((value->>'tracked')::boolean) FROM jsonb_array_elements(q.payload::jsonb->'lines') WHERE value->>'operation'='add' AND value->>'skuId'=hold.sku_id) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Inventory holds originate in the same confirmed quote and submit';END IF;
  IF hold.tracked=1 AND(SELECT coalesce(sum(before_quantity-after_quantity),0) FROM restaurant_stock_movements WHERE change_id=c.id AND sku_id=hold.sku_id AND kind IN('reserve','release'))<>(CASE WHEN hold.status IN('reserved','committed') THEN hold.quantity ELSE 0 END) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Tracked reservation net movements must equal the retained quantity';END IF;
 END IF;RETURN NULL;
END;$dg$;


CREATE OR REPLACE FUNCTION dg_native_order_withdraw_internal(change_value text,action_value text,expired_value boolean DEFAULT false) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE c restaurant_order_changes%ROWTYPE;o restaurant_orders%ROWTYPE;d restaurant_order_dispatches%ROWTYPE;created text;quote_value text;
BEGIN
 SELECT * INTO c FROM restaurant_order_changes WHERE id=change_value FOR UPDATE;SELECT * INTO o FROM restaurant_orders WHERE id=c.order_id FOR UPDATE;SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=c.id;SELECT created_at INTO created FROM _dg_native_dining_actions WHERE id=action_value;
 IF o.pending_change_id IS DISTINCT FROM c.id AND NOT(c.status='rejected' AND o.pending_change_id IS NULL) THEN PERFORM dg_native_order_error('ORDER_CHANGE_PENDING');END IF;
 IF c.status NOT IN('draft','awaiting_confirmation','confirmed','queued','rejected','stale') THEN PERFORM dg_native_order_error('ORDER_RESULT_PENDING');END IF;
 IF c.status='queued' THEN
  IF d.status<>'queued' OR d.attempts<>0 THEN PERFORM dg_native_order_error('ORDER_RESULT_PENDING');END IF;
  PERFORM dg_native_order_inventory(action_value,c.id,c.confirmed_quote_id,false);PERFORM dg_native_dining_effect(action_value,'restaurant_order_dispatches',c.id);UPDATE restaurant_order_dispatches SET status='cancelled',version=version+1,error_code=CASE WHEN expired_value THEN 'ORDER_SOURCE_EXPIRED' END,error_message=CASE WHEN expired_value THEN '未发送请求的原期限或来源已失效，预占已释放。' END,updated_at=created WHERE change_id=c.id;
 END IF;
 FOR quote_value IN SELECT id FROM restaurant_order_quotes WHERE change_id=c.id AND status='current' LOOP PERFORM dg_native_dining_effect(action_value,'restaurant_order_quotes',quote_value);UPDATE restaurant_order_quotes SET status=CASE WHEN expired_value AND expires_at<=dg_native_dining_now() THEN 'expired' ELSE 'withdrawn' END WHERE id=quote_value;END LOOP;
 PERFORM dg_native_dining_effect(action_value,'restaurant_order_changes',c.id);UPDATE restaurant_order_changes SET status=CASE WHEN expired_value THEN 'stale' ELSE 'withdrawn' END,version=version+1,updated_at=created WHERE id=c.id;
 PERFORM dg_native_dining_effect(action_value,'restaurant_orders',o.id);UPDATE restaurant_orders SET pending_change_id=NULL,status=CASE WHEN NOT EXISTS(SELECT 1 FROM restaurant_order_lines WHERE order_id=o.id AND quantity>cancelled_quantity) THEN 'cancelled' ELSE 'accepted' END,version=version+1,updated_at=created WHERE id=o.id;
END;$dg$;


CREATE FUNCTION dg_native_order_transport_final() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path FROM CURRENT AS $dg$
DECLARE j jsonb:=to_jsonb(NEW);d restaurant_order_dispatches%ROWTYPE;c restaurant_order_changes%ROWTYPE;line restaurant_order_lines%ROWTYPE;ticket restaurant_kitchen_tickets%ROWTYPE;receipt restaurant_pos_callbacks%ROWTYPE;lease _dg_native_order_worker_leases%ROWTYPE;line_origin _dg_native_order_line_origins%ROWTYPE;mock mock_pos_operations%ROWTYPE;snapshot jsonb;original_line jsonb;cancelled bigint;
BEGIN
 IF TG_TABLE_NAME='_dg_native_order_worker_leases' THEN
  SELECT * INTO lease FROM _dg_native_order_worker_leases WHERE lease_token=j->>'lease_token';SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=lease.change_id;
  IF lease.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR lease.request_hash<>d.request_hash OR lease.expires_at<>dg_native_people_iso(lease.created_at::timestamptz+interval '15 seconds') OR NOT EXISTS(SELECT 1 FROM _dg_native_dining_actions action WHERE action.id=lease.action_id AND action.kind=(CASE WHEN lease.mode='submit' THEN 'order_send' ELSE 'order_lookup' END) AND action.created_at=lease.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Worker lease has its exact original action, request and bounded deadline';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_dispatches' THEN
  SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=j->>'change_id';SELECT * INTO c FROM restaurant_order_changes WHERE id=d.change_id;
  IF d.attempts NOT IN(0,1) OR(d.lease_token IS NULL)<>(d.lease_until IS NULL) OR d.lease_token IS NOT NULL AND NOT EXISTS(SELECT 1 FROM _dg_native_order_worker_leases fixed WHERE fixed.lease_token=d.lease_token AND fixed.change_id=d.change_id AND fixed.request_hash=d.request_hash AND fixed.expires_at=d.lease_until AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1)) OR d.status IN('submitting','submitted','unknown','accepted','rejected') AND d.attempts<>1 OR d.status IN('accepted','rejected') AND NOT EXISTS(SELECT 1 FROM restaurant_pos_callbacks fact JOIN _dg_native_order_receipt_origins fixed ON fixed.event_id=fact.event_id WHERE fact.change_id=d.change_id AND fact.outcome=d.status AND fact.applied=1 AND fact.conflict=0) OR d.remote_request_id IS NOT NULL AND d.remote_request_id<>'mock-pos:'||d.change_id OR d.remote_order_id IS NOT NULL AND d.remote_order_id<>coalesce(d.request_payload::jsonb->>'remoteOrderId','mock-order:'||(d.request_payload::jsonb->>'orderId')) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Dispatch attempts, current lease and final facts require their immutable origins';END IF;
 ELSIF TG_TABLE_NAME='restaurant_pos_callbacks' THEN
  SELECT * INTO receipt FROM restaurant_pos_callbacks WHERE event_id=j->>'event_id';SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=receipt.change_id;
  IF d.attempts<>1 OR receipt.payload_hash<>dg_native_office_hash(jsonb_build_object('eventId',receipt.event_id,'receipt',receipt.payload::jsonb)) OR receipt.outcome IS DISTINCT FROM receipt.payload::jsonb->>'status' OR receipt.sequence IS DISTINCT FROM(receipt.payload::jsonb->>'sequence')::bigint OR receipt.applied NOT IN(0,1) OR receipt.conflict NOT IN(0,1) OR receipt.applied+receipt.conflict>1 OR NOT EXISTS(SELECT 1 FROM _dg_native_order_receipt_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.event_id=receipt.event_id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.request_hash=d.request_hash AND fixed.receipt_hash=dg_native_office_hash(receipt.payload::jsonb) AND fixed.created_at=receipt.created_at AND action.kind='order_receipt' AND action.created_at=receipt.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Every trusted receipt retains immutable payload, scope, ingress and local result';END IF;
 ELSIF TG_TABLE_NAME='mock_pos_operations' THEN
  SELECT * INTO mock FROM mock_pos_operations WHERE change_id=j->>'change_id';SELECT * INTO d FROM restaurant_order_dispatches WHERE change_id=mock.change_id;
  IF mock.request_hash<>d.request_hash OR mock.payload::jsonb IS DISTINCT FROM d.request_payload::jsonb OR mock.restaurant_id<>d.restaurant_id OR mock.remote_request_id<>'mock-pos:'||d.change_id OR mock.remote_order_id<>coalesce(d.request_payload::jsonb->>'remoteOrderId','mock-order:'||(d.request_payload::jsonb->>'orderId')) OR NOT EXISTS(SELECT 1 FROM _dg_native_order_mock_origins fixed JOIN _dg_native_dining_actions action ON action.id=fixed.action_id WHERE fixed.change_id=mock.change_id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fixed.payload_hash=dg_native_office_hash(to_jsonb(mock)) AND fixed.created_at=mock.created_at AND action.kind IN('order_mock_remote','order_mock_fixture') AND action.created_at=mock.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Local mock facts cannot replace the original request or claimed provider';END IF;
 ELSIF TG_TABLE_NAME='restaurant_order_lines' THEN
  SELECT * INTO line FROM restaurant_order_lines WHERE id=j->>'id';SELECT * INTO line_origin FROM _dg_native_order_line_origins WHERE line_id=line.id;SELECT q.payload::jsonb INTO snapshot FROM restaurant_order_quotes q WHERE id=line_origin.quote_id;SELECT value INTO original_line FROM jsonb_array_elements(snapshot->'lines') WHERE value->>'operation'='add' AND value->>'lineId'=line.id;
  IF line_origin.line_id IS NULL OR line_origin.change_id<>line.change_id OR line_origin.runtime_id<>(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) OR original_line IS NULL OR line_origin.line_hash<>dg_native_office_hash(original_line) OR line.order_id IS DISTINCT FROM snapshot->>'orderId' OR line.sku_id IS DISTINCT FROM original_line->>'skuId' OR line.item_id IS DISTINCT FROM original_line->>'itemId' OR line.item_name IS DISTINCT FROM original_line->>'itemName' OR line.sku_name IS DISTINCT FROM original_line->>'skuName' OR line.unit_price_minor IS DISTINCT FROM(original_line->>'unitPriceMinor')::bigint OR line.quantity IS DISTINCT FROM(original_line->>'quantity')::bigint OR line.preparation_note IS DISTINCT FROM original_line->>'preparationNote' OR line.dietary_tags::jsonb IS DISTINCT FROM original_line->'dietaryTags' OR(line.stock_tracked=1) IS DISTINCT FROM(original_line->>'tracked')::boolean OR NOT EXISTS(SELECT 1 FROM restaurant_pos_callbacks fact WHERE fact.event_id=line_origin.event_id AND fact.change_id=line.change_id AND fact.applied=1 AND fact.outcome='accepted' AND fact.created_at=line.created_at) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Accepted line identity, price, quantity and minimum kitchen information match the original quote and applied receipt';END IF;
  SELECT coalesce(sum((reduction->>'quantity')::bigint),0) INTO cancelled FROM restaurant_pos_callbacks fact JOIN restaurant_order_changes change ON change.id=fact.change_id JOIN restaurant_order_quotes quote ON quote.id=change.confirmed_quote_id CROSS JOIN LATERAL jsonb_array_elements(quote.payload::jsonb->'lines') reduction WHERE fact.applied=1 AND fact.outcome='accepted' AND reduction->>'operation'='reduce' AND reduction->>'lineId'=line.id;
  IF line.cancelled_quantity<>cancelled OR cancelled NOT BETWEEN 0 AND line.quantity THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Cancelled quantities require exact trusted reduction receipts';END IF;
 ELSE
  SELECT * INTO ticket FROM restaurant_kitchen_tickets WHERE id=j->>'id';SELECT * INTO line FROM restaurant_order_lines WHERE id=ticket.line_id;SELECT q.payload::jsonb INTO snapshot FROM _dg_native_order_line_origins fixed JOIN restaurant_order_quotes q ON q.id=fixed.quote_id WHERE fixed.line_id=line.id;
  IF NOT EXISTS(SELECT 1 FROM _dg_native_order_kitchen_origins fixed JOIN restaurant_pos_callbacks fact ON fact.event_id=fixed.event_id WHERE fixed.ticket_id=ticket.id AND fixed.line_id=line.id AND fixed.runtime_id=(SELECT runtime_id FROM _dg_native_runtime_control WHERE id=1) AND fact.outcome='accepted' AND fact.applied=1 AND fact.created_at=ticket.accepted_at) OR ticket.order_id<>line.order_id OR ticket.restaurant_id IS DISTINCT FROM snapshot->>'restaurantId' OR ticket.table_id IS DISTINCT FROM snapshot->>'tableId' OR ticket.table_name IS DISTINCT FROM snapshot->>'tableName' OR ticket.table_code IS DISTINCT FROM snapshot->>'tableCode' OR ticket.served_quantity<0 OR ticket.ready_quantity<ticket.served_quantity OR ticket.started_quantity<ticket.ready_quantity OR ticket.started_quantity+ticket.pending_cancel_quantity>line.quantity-line.cancelled_quantity OR ticket.pending_cancel_quantity<0 THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Kitchen scope, immutable table snapshot and monotone bounded quantities require the accepted line';END IF;
 END IF;RETURN NULL;
END;$dg$;
DO $transport_final$ DECLARE table_value text;BEGIN FOREACH table_value IN ARRAY ARRAY['_dg_native_order_worker_leases','restaurant_order_dispatches','restaurant_pos_callbacks','mock_pos_operations','restaurant_order_lines','restaurant_kitchen_tickets'] LOOP EXECUTE format('CREATE CONSTRAINT TRIGGER native_order_transport_final AFTER INSERT OR UPDATE ON %I DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION dg_native_order_transport_final()',table_value);END LOOP;END;$transport_final$;

DO $transport_acl$ DECLARE f record;BEGIN FOR f IN SELECT p.oid::regprocedure signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname=current_schema() AND p.proname LIKE 'dg_native_order_%' LOOP EXECUTE 'REVOKE ALL ON FUNCTION '||f.signature||' FROM PUBLIC';END LOOP;END;$transport_acl$;
